"""Actual GSC score-adapter bodies under typed Node stand-ins; not a game VM."""
from pathlib import Path
import argparse, json, re, subprocess, tempfile
from script_frame_diagnostics import function
def translate(body):
    masked=re.sub(r'//[^\n]*|/\*[\s\S]*?\*/|"(?:\\.|[^"\\])*"',lambda m:' '*len(m[0]),body)
    parameters=set(filter(None,(v.strip()for v in re.search(r'function\s+\w+\(([^)]*)\)',body)[1].split(','))))
    variables=set(re.findall(r'(?<![\w.])([A-Za-z_]\w*)\s*=(?!=)',masked))-parameters
    body=body.replace('self getentitynumber()','getentitynumber(self)').replace('self clientfield::increment_uimodel(cf)','native_increment(self,cf)')
    body=re.sub(r'\b([A-Za-z_]\w*)\.size\b',r'gsc_size(\1)',body)
    body=re.sub(r'\btrue\b','1',re.sub(r'\bfalse\b','0',body))
    opening=body.index('{')+1
    if variables:body=body[:opening]+'\nlet '+','.join(sorted(variables))+';\n'+body[opening:]
    return body
STANDINS="\nconst assert=require('node:assert/strict');let checks=0;\nfunction check(v,m){checks++;assert.ok(v,m);}\nfunction isdefined(v){return v!==undefined;}\nfunction isint(v){return Number.isInteger(v)&&v>=-2147483648&&v<=2147483647;}\nfunction isstring(v){return typeof v==='string';}\nfunction isentity(v){return v?.entity===true;}\nfunction isplayer(v){return isentity(v)&&v.player===true;}\nfunction gsc_size(v){return v.length;}\nfunction getsubstr(v,a,b){return v.slice(a,b);}\nfunction issubstr(v,s){return v.includes(s);}\nfunction getentitynumber(v){return v.num;}\nlet level={},self,dvars={},calls=[],writes=[],receipts=[];\nfunction getdvarint(k){return dvars[k]??0;}\nfunction getdvarstring(k){return dvars[k]??'';}\nfunction setdvar(k,v){dvars[k]=v;writes.push([k,v]);}\nfunction println(v){receipts.push(v);}\nconst nativeReturn={opaque:true};\nfunction native_increment(viewer,cf){calls.push({viewer,cf});return nativeReturn;}\nconst events=['damage','death_normal','death_torso','death_neck','death_head','death_melee'];\nfunction field(slot,event='damage'){return 'PlayerList.client'+slot+'.score_cf_'+event;}\nfunction player(num){return {entity:true,player:true,num,ready_for_score_events:1,score:500+num};}\nfunction reset(cap=8,map='zm_zod',epoch=17){\n level={eroded_coop_fields_revision:4};self=player(0);\n dvars={zm_coopStartupEpoch:epoch,mapname:map,zm_coopSchemaSlots:cap,zm_coopAppliedLimit:cap,\n zm_coopSchemaServerRevision:4,zm_coopSchemaServerContract:schema_contract(),zm_coopReadyEpoch:0,zm_coopReadyMap:'',zm_coopScoreEventStatus:'armed_for_known_module'};\n calls=[];writes=[];receipts=[];\n}\nfunction bind(cap=8,map='zm_zod',epoch=17){reset(cap,map,epoch);check(score_event_bind(epoch,map,cap)==1,'native-current bind');}\nfunction invoke(viewer,cf){self=viewer;return score_event_increment_uimodel(cf);}\nfunction declined(reason,active=false){\n check(level.eroded_coop_score_event_declined===1,'one-shot decline latch');\n check(dvars.zm_coopScoreEventStatus===reason&&dvars.zm_coopSchemaServerRevision===0&&dvars.zm_coopStatus==='declined_score_event_owner','explicit current-schema revocation');\n check(calls.length===0,'unsafe input never reaches native counter');\n const expected=active?['[Zombies coop] score_event=extra_delta_only','[Zombies coop] score_event=declined']:['[Zombies coop] score_event=declined'];\n check(JSON.stringify(receipts)===JSON.stringify(expected),'bounded exact one-shot receipts');\n}\n"
CASES="\n// All viewer/scorer/event combinations, including invalid participants outside\n// dynamic frozen capacity. Native delegates identify VIEWER independently.\nfor(let cap=5;cap<=8;cap++)for(let viewer=0;viewer<8;viewer++)for(let scorer=0;scorer<8;scorer++)for(const event of events){\n bind(cap);const p=player(viewer),score=p.score,name=field(scorer,event),out=invoke(p,name);\n check(p.score===score,'actual score untouched for every matrix case');\n if(viewer>=cap){declined('score_viewer_unrecognized');continue;}\n if(scorer>=cap){declined('score_slot_outside_capacity');continue;}\n if(scorer<4){check(out===nativeReturn&&calls.length===1&&calls[0].viewer===p&&calls[0].cf===name,'stock counter preserves exact receiver, argument and native return');check(writes.length===0&&receipts.length===0,'stock path emits no extra active claim');}\n else {check(out===undefined&&calls.length===0,'extra scorer cosmetic counter omitted');check(dvars.zm_coopScoreEventStatus==='owned_delta_only'&&receipts.length===1,'extra path reports exactly active delta-only');}\n check(dvars.zm_coopReadyEpoch===0&&score_event_current()==1,'bound/published schema permits legitimate early pre-controller-ready score calls');\n}\nbind();const earlyViewer=player(7);check(invoke(earlyViewer,field(0))===nativeReturn&&calls[0].viewer===earlyViewer,'viewer7 delegates scorer0 before ReadyEpoch');\nbind();check(invoke(player(0),field(4))===undefined&&calls.length===0,'viewer0 skips scorer4 before ReadyEpoch');\nbind();invoke(player(0),field(4));invoke(player(7),field(7));check(receipts.length===1&&writes.length===1,'extra activation one-shot');check(score_event_bind(17,'zm_zod',8)==1,'current rebind idempotent');\nfor(const bad of[undefined,null,{},[],17,true,'','PlayerList.client8.score_cf_damage','PlayerList.client04.score_cf_damage','PlayerList.client4.score_cf_custom','playerlist.client4.score_cf_damage','PlayerList.client4.score_cf_damage.extra','PlayerList.client4.score_cf_DAMAGE','PlayerList.client4.score_cf_','PlayerList.client-1.score_cf_damage','PlayerList.client4.score_cf_damage\\0']){\n bind();invoke(player(0),bad);declined('score_field_unrecognized');const before=JSON.stringify(writes);invoke(player(0),field(4));check(JSON.stringify(writes)===before,'decline cannot be revived');check(score_event_bind(17,'zm_zod',8)==0,'declined binding cannot be reused');\n}\nfor(const p of[undefined,{}, {entity:true,player:false},...[-1,8,1.5,'4',true,undefined].map(num=>player(num))]){bind();invoke(p,field(0));declined('score_viewer_unrecognized');}\nfor(const ready of[undefined,0,2,'1',{},false]){bind();let p=player(0);p.ready_for_score_events=ready;invoke(p,field(0));declined('score_viewer_unrecognized');}\nfor(const change of[()=>level.eroded_coop_fields_revision=3,()=>delete level.eroded_coop_fields_revision,()=>dvars.zm_coopSchemaServerRevision=0,()=>dvars.zm_coopSchemaServerContract='wrong']){bind();change();invoke(player(0),field(0));declined('score_context_unrecognized');}\n// Stale and malformed stored context must be inert, not clear a new VM receipt.\nfor(const change of[()=>dvars.zm_coopStartupEpoch++,()=>dvars.mapname='zm_tomb',()=>dvars.zm_coopSchemaSlots=7,()=>dvars.zm_coopAppliedLimit=7,\n ()=>delete level.eroded_coop_score_event_epoch,()=>level.eroded_coop_score_event_epoch='17',()=>level.eroded_coop_score_event_map={},()=>level.eroded_coop_score_event_map='bad/map',\n ()=>level.eroded_coop_score_event_capacity='8',()=>level.eroded_coop_score_event_capacity=4,()=>level.eroded_coop_score_event_capacity=9,()=>delete level.eroded_coop_score_event_capacity]){\n bind();change();const before=JSON.stringify(dvars);check(invoke(player(0),field(4))===undefined&&calls.length===0&&writes.length===0&&receipts.length===0&&JSON.stringify(dvars)===before,'stale or malformed context cannot poison current receipts');score_event_decline('old');check(writes.length===0,'explicit stale decline inert');\n}\nfor(const cap of[0,1,4,9,18,'8',8.5,true,undefined]){reset();const before=JSON.stringify(level);check(score_event_bind(17,'zm_zod',cap)==0&&JSON.stringify(level)===before,'bad bind capacity no mutation');}\nfor(const epoch of[0,-1,'17',17.5,true,undefined]){reset();check(score_event_bind(epoch,'zm_zod',8)==0&&writes.length===0,'bad bind epoch');}\nfor(const map of['','core_frontend','bad/map','bad\\\\map','bad.name','x'.repeat(65),{},17,undefined]){reset();check(score_event_bind(17,map,8)==0&&writes.length===0,'bad bind map');}\nfor(const map of['zm_zod','zm_castle','zm_stalingrad','workshop_custom','A_1-x']){bind(8,map);check(invoke(player(0),field(4))===undefined&&calls.length===0&&receipts.length===1,'same validated stock producer supports any current frozen ZM map');}\nconsole.log(JSON.stringify({passed:true,checks,scope:'Actual GSC proposal bodies mechanically translated; explicit typed entity/dvar/native delegates. No GSC VM/game/native import execution.'}));\n"

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('root',nargs='?',type=Path,default=Path(__file__).resolve().parents[1])
    parser.add_argument('--node',default='node')
    parser.add_argument('--output',type=Path)
    args=parser.parse_args()
    text=(args.root/'scripts/zombies_coop/eroded_coop_fields.gsc').read_text(encoding='utf-8')
    names=('schema_revision','schema_contract','castle_selector_map_valid','score_event_bind','score_event_bound_current','score_event_current','score_event_decline','score_event_field_slot','score_event_increment_uimodel')
    bodies=[function(text,'function '+n+'(')for n in names]
    helpers='\n'.join(bodies)
    assert not re.search(r'\b(wait|thread|waittill|endon)\b',re.sub(r'//[^\n]*','',helpers))
    assert not re.search(r'\.(score|pers|points)\s*=',helpers)
    assert 'ReadyEpoch' not in re.sub(r'//[^\n]*','',bodies[5])
    register=function(text,'function register_schema(')
    assert 'register("clientuimodel"'not in register
    assert register.index('score_event_bind(')<register.index('level.eroded_coop_fields_revision =')<register.index('setdvar("zm_coopSchemaServerRevision"')
    out=args.output or Path(tempfile.mkdtemp(prefix='boiii-score-events-'))
    out.mkdir(parents=True,exist_ok=True)
    script=out/'actual-score-functions.js'
    script.write_text(STANDINS+'\n'+'\n\n'.join(translate(b)for b in bodies)+'\n'+CASES,encoding='utf-8')
    run=subprocess.run([args.node,str(script)],capture_output=True,text=True,timeout=45)
    if run.returncode: raise AssertionError(run.stderr)
    result=json.loads(run.stdout)
    assert result['passed'] is True
    print(json.dumps(result))
if __name__=='__main__':main()
